using System;
using UnityEngine;

namespace Framework.Save.Integrations.EasySave
{
    /// <summary>
    /// Easy Save 3を利用した汎用データ保存クラス。
    ///
    /// ISaveProviderを実装し、ゲーム側がES3のAPIに
    /// 直接依存せずに保存処理を行えるようにする。
    ///
    /// インスタンスごとに専用の保存ファイルを管理する。
    /// 通常のファイル保存方式を使用する。
    /// </summary>
    public sealed class EasySaveProvider : ISaveProvider
    {
        #region Runtime Fields

        /// <summary>
        /// 管理対象となる保存ファイルのパス。
        /// </summary>
        private readonly string filePath;

        /// <summary>
        /// Easy Save 3の保存設定。
        /// </summary>
        private readonly ES3Settings settings;

        #endregion

        #region Properties

        /// <summary>
        /// 管理対象の保存ファイルパス。
        /// </summary>
        public string FilePath => filePath;

        #endregion

        #region Constructor

        /// <summary>
        /// 保存ファイルを指定してProviderを生成する。
        ///
        /// 保存先には通常のファイル保存方式を使用する。
        /// 相対パスの場合はES3の保存先設定を基準とする。
        /// </summary>
        /// <param name="filePath">
        /// 管理対象となる保存ファイルのパス
        /// </param>
        public EasySaveProvider(string filePath)
        {
            if (string.IsNullOrWhiteSpace(filePath))
            {
                throw new ArgumentException(
                    "保存ファイルのパスを指定してください。",
                    nameof(filePath));
            }

            this.filePath = filePath;

            // ES3の保存設定を生成する。
            settings = new ES3Settings(filePath);

            // キャッシュではなくファイルへ直接保存する。
            settings.location = ES3.Location.File;
        }

        #endregion

        #region Save Methods

        /// <summary>
        /// 指定されたキーにデータを保存する。
        ///
        /// 同じキーが存在する場合は上書きする。
        /// 保存失敗時は例外を呼び出し元へ通知する。
        /// </summary>
        /// <typeparam name="T">保存するデータ型</typeparam>
        /// <param name="key">保存データの識別キー</param>
        /// <param name="value">保存するデータ</param>
        public void Save<T>(string key, T value)
        {
            ValidateKey(key);

            ES3.Save<T>(
                key,
                value,
                settings);
        }

        #endregion

        #region Load Methods

        /// <summary>
        /// 指定されたキーのデータを読み込む。
        ///
        /// データが存在しない場合は初期値を返す。
        /// 読み込み失敗時は例外を呼び出し元へ通知する。
        /// </summary>
        /// <typeparam name="T">読み込むデータ型</typeparam>
        /// <param name="key">読み込むデータの識別キー</param>
        /// <param name="defaultValue">
        /// データが存在しない場合の初期値
        /// </param>
        /// <returns>読み込んだデータ、または初期値</returns>
        public T Load<T>(string key, T defaultValue)
        {
            ValidateKey(key);

            return ES3.Load<T>(
                key,
                defaultValue,
                settings);
        }

        /// <summary>
        /// 指定されたデータの読み込みを試みる。
        ///
        /// データが存在しない場合や読み込みに失敗した場合は
        /// falseを返す。
        ///
        /// 不正なキーの指定はプログラム上の問題として
        /// 例外を発生させる。
        /// </summary>
        /// <typeparam name="T">読み込むデータ型</typeparam>
        /// <param name="key">読み込むデータの識別キー</param>
        /// <param name="value">読み込んだデータ</param>
        /// <returns>読み込みに成功した場合はtrue</returns>
        public bool TryLoad<T>(string key, out T value)
        {
            ValidateKey(key);

            value = default(T);

            try
            {
                // データが存在しない場合は読み込まない。
                if (!Exists(key))
                {
                    return false;
                }

                value = ES3.Load<T>(
                    key,
                    settings);

                return true;
            }
            catch (Exception exception)
            {
                // 読み込み失敗時は型の既定値を返す。
                value = default(T);

                Debug.LogWarning(
                    $"保存データの読み込みに失敗しました。\n" +
                    $"ファイル：{filePath}\n" +
                    $"キー：{key}\n" +
                    $"原因：{exception.Message}");

                return false;
            }
        }

        #endregion

        #region Data Management Methods

        /// <summary>
        /// 指定されたキーの保存データが存在するか確認する。
        /// </summary>
        /// <param name="key">確認するデータの識別キー</param>
        /// <returns>データが存在する場合はtrue</returns>
        public bool Exists(string key)
        {
            ValidateKey(key);

            return ES3.KeyExists(
                key,
                settings);
        }

        /// <summary>
        /// 管理対象の保存ファイルが存在するか確認する。
        /// </summary>
        /// <returns>ファイルが存在する場合はtrue</returns>
        public bool FileExists()
        {
            return ES3.FileExists(settings);
        }

        /// <summary>
        /// 指定されたキーの保存データを削除する。
        ///
        /// データが存在しない場合は何も行わない。
        /// </summary>
        /// <param name="key">削除するデータの識別キー</param>
        public void Delete(string key)
        {
            ValidateKey(key);

            if (!Exists(key))
            {
                return;
            }

            ES3.DeleteKey(
                key,
                settings);
        }

        /// <summary>
        /// 管理対象の保存ファイルを削除する。
        ///
        /// ファイル内のすべてのキーが削除される。
        /// 異なる保存ファイルには影響を与えない。
        /// </summary>
        public void DeleteAll()
        {
            if (!FileExists())
            {
                return;
            }

            ES3.DeleteFile(settings);
        }

        /// <summary>
        /// 保留中の保存処理を確定する。
        ///
        /// 現在は即時保存方式を使用しているため、
        /// 追加の処理は必要ない。
        /// </summary>
        public void Flush()
        {
            // 即時保存方式のため処理なし。
        }

        #endregion

        #region Validation Methods

        /// <summary>
        /// 保存データの識別キーが有効か検証する。
        /// </summary>
        /// <param name="key">検証する識別キー</param>
        private static void ValidateKey(string key)
        {
            if (string.IsNullOrWhiteSpace(key))
            {
                throw new ArgumentException(
                    "保存データのキーを指定してください。",
                    nameof(key));
            }
        }

        #endregion
    }
}
